// unity-bridge.js — Unity bridge install helpers (v0.5.0).
//
// Plain Node, no Electron dependency, so the smoke test can exercise
// this file directly with `node`. main.js requires it for the
// unity:installBridge / unity:ensureBridge IPCs.
//
// Source resolution order for the bridge file:
//   1. the bundled file <app>/unity-companion/CodeFoxBridge.cs, and
//   2. the embedded copy in unity-bridge-source.js (generated by
//      scripts/embed-bridge.js from that same .cs file).
// There is no third outcome that tells the user to copy the file by
// hand: if both sources are unreadable, install reports the real
// error (reinstall the app) instead.

const fs = require('fs');
const path = require('path');

// Version of the bridge bundled with this build. This MUST move with
// package.json's version whenever the bridge file changes — the app
// compares it against the version marker inside the installed bridge
// (see getInstalledBridgeVersion) to decide whether an installed
// bridge is out of date. The .cs file carries the same version in
// its "// CodeFoxBridge version: X.Y.Z" marker and BridgeVersion const.
const BUNDLED_BRIDGE_VERSION = '0.14.0';

// The oldest bridge that speaks the .bridge/ transport (protocol 1,
// inbox/outbox/heartbeat). The app never sends an inbox command to
// anything older — main.js updates the bridge first, and
// unity-command.js refuses as a safety net. Stays at 0.12.0 even
// as the bundled version moves on: a 0.12.0 bridge still speaks
// protocol 1.
const MIN_TRANSPORT_VERSION = '0.12.0';

// Compare "a.b.c" versions numerically. Returns <0, 0, or >0.
function compareVersions(a, b) {
  const pa = String(a || '0.0.0').split('.').map(n => parseInt(n, 10) || 0);
  const pb = String(b || '0.0.0').split('.').map(n => parseInt(n, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d !== 0) return d;
  }
  return 0;
}

function bridgeDiskPath(appDir) {
  return path.join(appDir, 'unity-companion', 'CodeFoxBridge.cs');
}

function bridgeDestPath(projectPath) {
  return path.join(projectPath, 'Assets', 'Editor', 'CodeFoxBridge.cs');
}

function bridgeInstalled(projectPath) {
  if (!projectPath) return false;
  try { return fs.existsSync(bridgeDestPath(projectPath)); } catch { return false; }
}

// Version of the bridge installed in a project, read from the
// "// CodeFoxBridge version: X.Y.Z" marker in the installed file.
// Returns null when the file is missing or has no marker — an
// unmarked bridge (e.g. installed by CodeFox <= 0.5.1, which had no
// marker) is treated as version "0.0.0", i.e. out of date.
function getInstalledBridgeVersion(projectPath) {
  if (!bridgeInstalled(projectPath)) return null;
  try {
    const source = fs.readFileSync(bridgeDestPath(projectPath), 'utf8');
    const m = /CodeFoxBridge version:\s*([0-9]+\.[0-9]+\.[0-9]+)/.exec(source);
    return m ? m[1] : null;
  } catch { return null; }
}

// True when the installed bridge is missing, unmarked, or older than
// the bundled one. False when it is current.
function isBridgeUpdateAvailable(projectPath) {
  if (!bridgeInstalled(projectPath)) return true;
  const installed = getInstalledBridgeVersion(projectPath);
  if (!installed) return true;
  return compareVersions(installed, BUNDLED_BRIDGE_VERSION) < 0;
}

// The embedded copy, or null when it cannot be read.
function embeddedSource() {
  try {
    const mod = require('./unity-bridge-source');
    if (mod && typeof mod.BRIDGE_SOURCE === 'string' && mod.BRIDGE_SOURCE.length > 100) {
      return mod.BRIDGE_SOURCE;
    }
  } catch {}
  return null;
}

// { ok, source, from: 'disk' | 'embedded' } or { ok:false, error }.
function resolveBridgeSource(appDir) {
  const disk = bridgeDiskPath(appDir);
  try {
    if (fs.existsSync(disk)) {
      const source = fs.readFileSync(disk, 'utf8');
      if (source && source.length > 100) return { ok: true, source, from: 'disk' };
    }
  } catch {}
  const embedded = embeddedSource();
  if (embedded) return { ok: true, source: embedded, from: 'embedded' };
  return {
    ok: false,
    error: 'Bridge source is missing from the app install: neither the bundled unity-companion/CodeFoxBridge.cs file nor the embedded copy could be read. Reinstall CodeFox.',
  };
}

// True when the installed bridge speaks the .bridge/ transport
// (protocol 1). False when it is missing, unmarked, or older than
// 0.12.0 — an old bridge never sees the inbox, so the app must
// update it before sending a command.
function hasTransportBridge(projectPath) {
  const installed = getInstalledBridgeVersion(projectPath);
  if (!installed) return false;
  return compareVersions(installed, MIN_TRANSPORT_VERSION) >= 0;
}

// The bridge protocol files live in <project>/.bridge/ and must
// never be committed to the project's repo — they are per-machine
// state (inbox, outbox, heartbeat), not project files. Appends
// ".bridge/" to the project's .gitignore when the file exists and
// does not already list it. Best-effort: never fails the install.
// Only appends when a .gitignore already exists — creating one
// just for this would be a surprise.
function ensureProjectGitignore(projectPath) {
  if (!projectPath) return false;
  const gitignorePath = path.join(projectPath, '.gitignore');
  try {
    if (!fs.existsSync(gitignorePath)) return false;
    const content = fs.readFileSync(gitignorePath, 'utf8');
    const listed = content.split(/\r?\n/).some(l => {
      const t = l.trim();
      return t === '.bridge/' || t === '.bridge' || t === '/.bridge/' || t === '/.bridge';
    });
    if (listed) return false;
    const sep = content.length && !content.endsWith('\n') ? '\n' : '';
    fs.writeFileSync(gitignorePath, content + sep + '# CodeFox bridge protocol files (per-machine, never committed)\n.bridge/\n', 'utf8');
    return true;
  } catch { return false; }
}

// Legacy protocol files from bridges before 0.12.0, which used
// Assets/.codefox-command.json and Assets/.codefox-result.json (and
// the refresh sentinel in Assets). The new bridge never reads
// them; deleting them on update stops a stale command file from
// lingering in the project. Best-effort — a missing file is fine.
function deleteLegacyProtocolFiles(projectPath) {
  if (!projectPath) return;
  for (const name of ['.codefox-command.json', '.codefox-result.json', '.codefox-refresh-trigger']) {
    try {
      const p = path.join(projectPath, 'Assets', name);
      if (fs.existsSync(p)) fs.unlinkSync(p);
    } catch { /* best-effort */ }
  }
}

// Write the bridge into <project>/Assets/Editor/CodeFoxBridge.cs
// (creating the folder if needed). Returns { ok, dest, from } or
// { ok:false, error } with the real filesystem error.
function installBridgeFile(projectPath, appDir) {
  if (!projectPath || !fs.existsSync(projectPath)) {
    return { ok: false, error: 'No project folder set.' };
  }
  const resolved = resolveBridgeSource(appDir);
  if (!resolved.ok) return resolved;
  const dest = bridgeDestPath(projectPath);
  try {
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    fs.writeFileSync(dest, resolved.source, 'utf8');
    // A new bridge speaks the new transport: the legacy protocol
    // files are dead weight, and .bridge/ belongs in .gitignore.
    deleteLegacyProtocolFiles(projectPath);
    ensureProjectGitignore(projectPath);
    return { ok: true, dest, from: resolved.from };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

// Install the bridge for a project, or update it when the installed
// copy is older than the bundled one (v0.5.2: v0.5.1 and earlier only
// installed when the file was missing, so a broken bridge installed
// by an older CodeFox would never be replaced).
//   opts.enabled === false — the user toggled the bridge off for this
//     project. Never install or update; returns { ok:false, skipped,
//     disabled:true }. This is what stops the toggle-off bug: the
//     Connections view re-renders right after a removal, and without
//     this flag its auto-install would put the bridge straight back.
// Skips (ok:false, skipped:true) when the folder has no Assets
// folder — it is not a Unity project — and no-ops (ok:true,
// already:true) when the installed bridge is already current.
// An update returns { ok:true, updated:true, fromVersion, toVersion }.
function ensureBridge(projectPath, appDir, opts) {
  if (!projectPath || !fs.existsSync(projectPath)) {
    return { ok: false, error: 'No project folder set.' };
  }
  if (opts && opts.enabled === false) {
    return { ok: false, skipped: true, disabled: true, error: 'Bridge is disabled for this project — turn it on in Settings → Connections.' };
  }
  if (!fs.existsSync(path.join(projectPath, 'Assets'))) {
    return { ok: false, skipped: true, error: 'No Assets folder in this project — not a Unity project, so the bridge was not installed.' };
  }
  if (!bridgeInstalled(projectPath)) return installBridgeFile(projectPath, appDir);
  if (!isBridgeUpdateAvailable(projectPath)) {
    return { ok: true, already: true, version: getInstalledBridgeVersion(projectPath) };
  }
  const fromVersion = getInstalledBridgeVersion(projectPath) || '0.0.0';
  const installed = installBridgeFile(projectPath, appDir);
  if (!installed.ok) return installed;
  return { ...installed, updated: true, fromVersion, toVersion: BUNDLED_BRIDGE_VERSION };
}

module.exports = {
  BUNDLED_BRIDGE_VERSION,
  MIN_TRANSPORT_VERSION,
  compareVersions,
  getInstalledBridgeVersion,
  isBridgeUpdateAvailable,
  hasTransportBridge,
  ensureProjectGitignore,
  deleteLegacyProtocolFiles,
  bridgeDiskPath,
  bridgeDestPath,
  bridgeInstalled,
  embeddedSource,
  resolveBridgeSource,
  installBridgeFile,
  ensureBridge,
};
